import {
	Component,
	Element,
	Event,
	type EventEmitter,
	Host,
	Listen,
	Method,
	Prop,
	State,
	Watch,
	h,
} from "@stencil/core";
import { nav } from "../../../icons/index";
import { focusVisible } from "../../utils/focus-visible";
import getBootstrapConfig from "../../utils/getBootstrapConfig";

/**
 * @since 0.0.11
 * @status stable
 *
 * @data-testid collapse-button - The control that collapses or expands the shell navigation.
 *
 * @slot - slot, containing nav items
 *
 * @part base - The component's base wrapper.
 * @part nav-container - The wrapper containing collapsible-icon and nav items
 * @part nav - Part for area containing nav items
 * @part collapsible-icon - Collapsible icon specific part
 */

@Component({
	tag: "hbr-shell-nav",
	styleUrl: "shell-nav.scss",
	shadow: true,
})
export class ShellNav {
	bodyRef: HTMLElement;
	baseRef: HTMLElement;
	navItemContainerRef: HTMLElement;
	collapseIconRef: HTMLElement;
	hoverTimeoutId: NodeJS.Timeout = null;

	private defaultAria: {
		collapseBtnAriaExpand: string;
		collapseBtnAriaCollapse: string;
	} = {
		collapseBtnAriaCollapse: "Collapse navigation",
		collapseBtnAriaExpand: "Expand navigation",
	};

	/** Reference to the active(hover or selected) item */
	@State() activeItem: HTMLHbrNavItemElement | null;

	/** selected nav panel item, this is CASCADING, meaning nav is select, only its drawer item is selected */
	@State() selectedItem: HTMLHbrNavItemElement | null;

	/** Selected menu item (popover to the right) */
	@State() selectedMenuItem: HTMLHbrMenuItemElement | null = null;

	/** Checks if shell nav got activated by click (not hover) */
	@State() isActiveFromClick = false;

	/** No transform if element is already selected */
	@State() noTransform = false;

	/** Checks if screenSize is in reduced state */
	@State() inCompactView = false;

	@Element() host: HTMLHbrShellNavElement;

	/** make this component no responsive */
	@Prop({ reflect: true }) noResponsive = false;

	/** label to be attached to collapse icon in component body area */
	@Prop({ reflect: true }) collapseLabel = "";

	@Prop({ reflect: true }) aria: {
		collapseBtnAriaExpand?: string;
		collapseBtnAriaCollapse?: string;
	};

	/** label to be shown in tooltip attached to collapse icon */
	@Prop({ reflect: true }) collapseTooltipLabel = "Collapse";

	/** label to be shown in tooltip attached to collapse icon */
	@Prop({ reflect: true }) disableCollapseTooltip = false;

	/** sets side nav in collapsed state */
	@Prop({ mutable: true, reflect: true }) collapsed = false;

	/** when in collapsed state, hides title and shows only icon if true */
	@Prop({ reflect: true }) titleless = false;

	/** Emitted when nav item or menu item in 2d level nav (drawer) is being selected */
	@Event({ eventName: "hbr-nav-item-click" }) hbrNavItemClick: EventEmitter;

	/** Emitted when collapsible icon is being clicked */
	@Event({ eventName: "hbr-collapse-click" }) hbrCollapseClick: EventEmitter;

	/** Emitted when active item is being set */
	@Event({ eventName: "hbr-select" }) hbrItemSelect: EventEmitter;

	/** Use re-selectable to force 'hbr-nav-item-click' event to fire on click instead of on change */
	@Prop() reselectable = false;

	/** Show Collapse icon on top */
	@Prop() showCollapseButton = true;

	/** Hover timer for hover event */
	@Prop() hoverTimer = 400;

	/** Max width of the compact view */
	@Prop() compactViewWidth = 980;

	/** Disable click the same nav-item to close behavior */
	@Prop({ reflect: true }) disableClickToClose = false;

	@Method()
	async resetSelected() {
		this.selectedItem = null;
		this.selectedMenuItem = null;
	}

	/** Emitted when collapsed by resize */
	@Event({ eventName: "hbr-collapse" }) hbrCollapse: EventEmitter;

	/** Emitted when expanded by resize */
	@Event({ eventName: "hbr-expand" }) hbrExpand: EventEmitter;

	@Watch("activeItem")
	activeItemWatcher(activeItem) {
		this.hbrItemSelect.emit(activeItem);
		if (!activeItem) {
			this.getAllItems().forEach((item) => {
				const popover = this.getPopoverContent(item);
				if (popover) {
					item.active = false;
					this.noTransform = false;
				}
			});
		} else {
			this.getAllItems().forEach((item) => {
				const popover = this.getPopoverContent(item);
				if (popover) {
					item.active = item === activeItem;
				}
			});
		}
	}

	@Watch("noTransform")
	noTransformWatcher(noTransform) {
		this.getAllItems().forEach((item) => {
			const popover = this.getPopoverContent(item);
			if (popover) {
				item.noTransform = noTransform;
			}
		});
	}

	@Watch("selectedItem")
	selectedItemWatcher(selectedItem) {
		// to deal with undefined
		if (selectedItem) {
			this.getAllItems().forEach((item) => {
				item.selected = item === selectedItem;
			});
			//emit event for nav item click
			if (this.selectedMenuItem === null) {
				this.hbrNavItemClick.emit({
					selectedItem: selectedItem,
					selectedMenuItem: this.selectedMenuItem,
				});
			}
		}
	}

	@Watch("selectedMenuItem")
	selectedMenuWatcher(selectedMenuItem) {
		if (
			selectedMenuItem !== null &&
			!selectedMenuItem.hasAttribute("has-children")
		) {
			this.setMenuItemValue(selectedMenuItem);
		} else {
			this.setMenuItemValue(null);
		}
	}

	setMenuItemValue = (activeItem: HTMLHbrMenuItemElement) => {
		const navItems = this.host.querySelectorAll("hbr-nav-item");
		navItems?.forEach((item) => {
			item.querySelectorAll("hbr-menu-item")?.forEach((menuItem) => {
				const condition = activeItem && menuItem.value === activeItem.value;
				menuItem.checked = condition;
				menuItem.checkMark = condition;
			});
		});
	};

	getPopoverContent = (element) => {
		const slot = element.shadowRoot.querySelector(
			'slot[name="menu"]',
		) as HTMLSlotElement;
		if (slot?.assignedNodes()?.length) {
			return slot.assignedNodes()[0];
		}
	};

	@Listen("hbr-hover")
	itemHoverListener(event: CustomEvent) {
		//checking clicked or not
		if (this.isActiveFromClick) return;
		// checking if hovered on ordinary item or with popover
		if (!event.detail?.popover) {
			this.activeItem = null;
			this.isActiveFromClick = false;
		} else {
			// else if with popover
			if (this.activeItem === event.target) {
				return;
			}
			if (!this.activeItem && this.isActiveFromClick === false) {
				this.hoverTimeoutId = setTimeout(() => {
					this.activeItem = event.target as HTMLHbrNavItemElement;
				}, this.hoverTimer);
			} else {
				this.noTransform = true;
				this.activeItem = event.target as HTMLHbrNavItemElement;
			}
		}
	}

	@Listen("hbr-leave")
	itemLeaveListener() {
		if (this.hoverTimeoutId) {
			clearTimeout(this.hoverTimeoutId);
		}
	}

	@Listen("hbr-click")
	async itemClickListener(event: CustomEvent) {
		const targetElm = event.target as HTMLElement;
		// checking if hovered on ordinary or popover

		// if hbr-click comes back without popover, it means nav-item is closed
		// OR if the previous active item was from a click action,
		// and now the new clicked item is the same as the previous active item,
		// then we close the popover
		if (
			!event.detail?.popover ||
			(this.isActiveFromClick &&
				targetElm.tagName.toLowerCase() === "hbr-menu-item" &&
				this.activeItem === event.target)
		) {
			if (this.selectedMenuItem) {
				this.selectedMenuItem = null;
			}
			this.isActiveFromClick = false;
			if (this.reselectable) {
				this.selectedItem = undefined;
			}
			this.selectedItem = targetElm as HTMLHbrNavItemElement;

			this.activeItem = null;
		} else {
			this.isActiveFromClick = true;
			// hiding existing active item
			if (this.activeItem !== targetElm) {
				this.noTransform = false;
				this.activeItem = targetElm as HTMLHbrNavItemElement;
			} else if (targetElm.tagName.toLowerCase() === "hbr-nav-item") {
				if (!this.disableClickToClose) {
					this.onDrawerClose();
				}
			}
			if (event.detail?.keyboard) {
				setTimeout(() => {
					targetElm.shadowRoot
						.querySelector<HTMLInputElement>(".nav-item__drawer-close")
						.focus();
				}, 100);
			}
		}
	}

	@Listen("hbr-hide")
	async drawerCloseListener(event: CustomEvent) {
		const target = event.target as HTMLElement;

		if (target.tagName.toLowerCase() === "hbr-nav-item") {
			this.onDrawerClose(event?.detail);
		}
		if (target.tagName.toLowerCase() === "hbr-shell-nav") {
			this.isActiveFromClick = false;
			this.activeItem = null;
		}
	}

	@Listen("click", { capture: true, target: "document" })
	handleClickOutside(event: MouseEvent) {
		const target = event.target as HTMLElement;
		// if clicked outside of the navigation, close the drawer
		if (this.activeItem && !this.host.contains(target)) {
			this.onDrawerClose(true);
		}
	}

	@Listen("hbr-nav-item-select")
	async selectItemListener(event: CustomEvent) {
		this.selectedItem = event?.detail;
	}

	onDrawerClose = (shouldFocus = false) => {
		if (shouldFocus) {
			this.activeItem?.setFocus();
		}
		this.isActiveFromClick = false;
		this.noTransform = false;
		this.activeItem = null;
	};

	@Listen("hbr-select")
	async menuItemListener(event) {
		if (event.target.tagName.toLowerCase() === "hbr-menu") {
			this.isActiveFromClick = true;
			const menuItem = event.detail?.item;
			this.selectedMenuItem = menuItem;
			const navItem = menuItem?.closest("hbr-nav-item");
			if (!navItem?.switcher) {
				if (this.reselectable) {
					this.selectedItem = undefined;
				}
				this.selectedItem = navItem;
			}
			this.hbrNavItemClick.emit({
				selectedItem: navItem,
				selectedMenuItem: menuItem,
			});

			// check if it is a switcher or the menu item clicked has sub menu
			if (!navItem?.switcher && !menuItem.hasAttribute("has-children")) {
				this.selectedItem?.setFocus();
				this.selectedItem?.drawerClose();
			}
		}
	}

	onMouseLeave = async () => {
		if (this.isActiveFromClick) return;
		this.activeItem = null;
	};

	componentDidLoad() {
		this.setView();
		this.setCollapsedEntry();
		window.addEventListener("resize", this.setView);
		// Set initial items state when the items first become visible
		const observer = new IntersectionObserver((entries, observer) => {
			if (entries[0].intersectionRatio > 0) {
				this.setAriaLabels();
				observer.unobserve(entries[0].target);
			}
		});
		observer.observe(this.host);
		focusVisible.observe(this.baseRef);
	}

	disconnectedCallback() {
		focusVisible.unobserve(this.baseRef);
		window.removeEventListener("resize", this.setView);
	}

	setView = () => {
		const prevScreenWidthReduced = this.inCompactView;
		const screenWidthReduced = window.innerWidth < this.compactViewWidth;

		if (prevScreenWidthReduced !== screenWidthReduced) {
			this.inCompactView = screenWidthReduced;
			if (this.inCompactView) {
				this.hbrCollapse.emit();
				this.collapsed = true;
			} else {
				this.hbrExpand.emit();
				this.collapsed = false;
			}
		}
	};

	@Watch("collapsed")
	handleCollapsedChange() {
		this.setCollapsedEntry();
	}

	@Watch("titleless")
	handleTitlelessChange() {
		this.setCollapsedEntry();
	}

	@Watch("inCompactView")
	handleInCompactViewChange() {
		this.setCollapsedEntry();
	}

	setCollapsedEntry = () => {
		const collapsedByPropOrScreenWidth =
			this.collapsed || (!this.noResponsive && this.inCompactView);
		this.getAllItems().forEach((item) => {
			item.collapsed = collapsedByPropOrScreenWidth;
			item.titleless = collapsedByPropOrScreenWidth && this.titleless;
		});
		this.getAllGroups().forEach((label) => {
			label.collapsed = collapsedByPropOrScreenWidth;
		});
	};

	getAllItems = (ele?) => {
		let slot = ele;
		if (!ele) slot = this.navItemContainerRef?.querySelector("slot");
		const slotList = slot ? [...slot.assignedElements()] : [];
		const pushItems = (acc, cur) => {
			if (cur.tagName.toLowerCase() === "hbr-nav-item") {
				acc.push(cur);
			} else if (cur.tagName.toLowerCase() === "hbr-nav-group") {
				return [...cur.children].reduce(pushItems, acc);
			} else {
				// account for nav-item nested deeply in other elements
				const deeplyNestedItem = cur.querySelector?.("hbr-nav-item");
				if (deeplyNestedItem) {
					acc.push(deeplyNestedItem);
				}
			}
			return acc;
		};
		return slotList.reduce(pushItems, []);
	};

	getAllGroups = (ele?) => {
		let slot = ele;
		if (!ele) slot = this.navItemContainerRef?.querySelector("slot");
		const slotList = slot ? [...slot.assignedElements()] : [];
		const itemsList = slotList.reduce((acc, cur) => {
			if (cur.tagName.toLowerCase() === "hbr-nav-group") acc.push(cur);
			return acc;
		}, []);
		return itemsList;
	};

	getAllLabels = (ele?) => {
		let slot = ele;
		if (!ele) slot = this.navItemContainerRef?.querySelector("slot");
		const slotList = slot ? [...slot.assignedElements()] : [];
		const itemsList = slotList.reduce((acc, cur) => {
			if (cur.tagName.toLowerCase() === "hbr-nav-label") acc.push(cur);
			return acc;
		}, []);
		return itemsList;
	};

	getAllPanels() {
		const slot = this.bodyRef.querySelector("slot");
		return [...slot.assignedElements()].filter(
			(el: Element) => el.tagName.toLowerCase() === "hbr-tab-panel",
		) as [HTMLHbrTabPanelElement];
	}

	setAriaLabels() {
		const items = this.getAllItems();
		const panels = this.getAllPanels();

		// Link each tab with its corresponding panel
		items.map((tab) => {
			const panel = panels.find((el) => el.name === tab.panel);
			if (panel) {
				tab.setAttribute("aria-controls", panel.getAttribute("id"));
				panel.setAttribute("aria-labelledby", tab.getAttribute("id"));
			}
		});
	}

	toggleCollapsed = () => {
		this.hbrCollapseClick.emit();
	};

	onShellNavKeyDown = (event: KeyboardEvent) => {
		const target = event.target as HTMLElement;
		if (target.tagName.toLowerCase() === "hbr-nav-item") {
			if (event.key === "ArrowDown") {
				const allNavItems = [...this.host.querySelectorAll("hbr-nav-item")];
				const focusedIdx = allNavItems.findIndex((item) => {
					return this.host.ownerDocument.activeElement === item;
				});
				if (focusedIdx < allNavItems.length - 1) {
					allNavItems[focusedIdx]?.removeFocus?.();
					allNavItems[focusedIdx + 1]?.setFocus?.();
				}
				event.preventDefault();
			} else if (event.key === "ArrowUp") {
				const allNavItems = [...this.host.querySelectorAll("hbr-nav-item")];
				const focusedIdx = allNavItems.findIndex((item) => {
					return this.host.ownerDocument.activeElement === item;
				});
				if (focusedIdx > 0) {
					allNavItems[focusedIdx]?.removeFocus?.();
					allNavItems[focusedIdx - 1]?.setFocus?.();
				}
				event.preventDefault();
			}
		}
	};

	render() {
		const customSystemIcons = getBootstrapConfig()?.systemIcons;
		const collapsedByPropOrScreenWidth =
			this.collapsed || (!this.noResponsive && this.inCompactView);
		return (
			<Host>
				<div
					part="base"
					ref={(el) => {
						this.baseRef = el;
					}}
					class={{
						nav: true,
						"nav--collapsed": collapsedByPropOrScreenWidth,
						"nav--titleless": collapsedByPropOrScreenWidth && this.titleless,
					}}
				>
					<div
						part="nav-container"
						class={{
							"nav__nav-container": true,
							"nav__nav-container-no-responsive": this.noResponsive,
						}}
						onMouseLeave={this.onMouseLeave}
					>
						<div
							class={{
								"nav__collapse-icon": true,
								"nav__collapse-icon-collapsed": collapsedByPropOrScreenWidth,
								"nav__collapse-icon-hidden":
									this.inCompactView || !this.showCollapseButton,
								"nav__collapse-icon-titleless":
									collapsedByPropOrScreenWidth && this.titleless,
							}}
							part="collapsible-icon"
						>
							<div
								class={{
									"nav__collapse-icon-wrapper": true,
									"nav__collapse-icon-wrapper-collapsed":
										collapsedByPropOrScreenWidth,
									"nav__collapse-icon-wrapper-titleless":
										collapsedByPropOrScreenWidth && this.titleless,
								}}
								onClick={this.toggleCollapsed}
								onKeyDown={(e) => {
									e.key === "Enter" && this.toggleCollapsed();
								}}
								tabIndex={0}
								ref={(el) => {
									this.collapseIconRef = el;
								}}
								data-testid="collapse-button"
								part="collapse-button"
								// biome-ignore lint/a11y: use the same element as before for accessibility
								aria-label={
									this.collapsed
										? this.aria?.collapseBtnAriaExpand ||
										  this.defaultAria.collapseBtnAriaExpand
										: this.aria?.collapseBtnAriaCollapse ||
										  this.defaultAria.collapseBtnAriaCollapse
								}
								role="button"
							>
								<hbr-icon asset={customSystemIcons?.nav || nav} />
								{!this.collapsed && this.collapseLabel && (
									<div part="collapse-label" class="nav__collapse-label">
										{this.collapseLabel}
									</div>
								)}
							</div>
						</div>
						<div key="nav" part="nav" class="nav__nav">
							<div
								part="nav-items"
								ref={(el) => {
									this.navItemContainerRef = el;
								}}
								onKeyDown={this.onShellNavKeyDown}
								class={{
									nav__items: true,
									"nav__items-nav--collapsed": collapsedByPropOrScreenWidth,
									"nav__items-nav--titleless":
										collapsedByPropOrScreenWidth && this.titleless,
								}}
								role="menu"
								aria-orientation="vertical"
							>
								<slot />
							</div>
						</div>
					</div>
					<div
						ref={(el) => {
							this.bodyRef = el;
						}}
						part="body"
						class="nav__body"
					>
						<slot name="content" />
					</div>
				</div>
				<hbr-portal>
					<hbr-tooltip
						class="hbr-shell-nav__collapse-tooltip"
						content={this.collapseTooltipLabel}
						disabled={this.disableCollapseTooltip}
						skidding={3}
						distance={5}
						placement="left-start"
						anchor={this.collapseIconRef}
					/>
				</hbr-portal>
			</Host>
		);
	}
}
